package com.sergio.financial.budget; import jakarta.validation.Valid; import java.time.YearMonth; import java.util.*; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/budgets") public class BudgetController {private final BudgetService service; public BudgetController(BudgetService s){service=s;} @PutMapping("/{categoryId}") public BudgetResponse put(@PathVariable Long categoryId,@RequestParam YearMonth month,@Valid @RequestBody BudgetRequest r,Authentication a){return service.upsert(Long.valueOf(a.getName()),categoryId,month,r);} @GetMapping public List<BudgetResponse> get(@RequestParam YearMonth month,Authentication a){return service.list(Long.valueOf(a.getName()),month);}}
